/// The catalog row for `name`, when it is a standard dangerous permission.
#[must_use]
pub fn permission(name: &str) -> Option<&'static CatalogPermission> {
    PERMISSIONS.iter().find(|row| row.name == name)
}

/// The catalog row for the group `name` (full or short form).
#[must_use]
pub fn group(name: &str) -> Option<&'static CatalogGroup> {
    let short = name.rsplit('.').next().unwrap_or(name);
    GROUPS
        .iter()
        .find(|row| row.name == name || row.name.ends_with(&format!(".{short}")))
}

/// Every catalog permission in `group` (short or full group name).
#[must_use]
pub fn permissions_in_group(group_name: &str) -> Vec<&'static CatalogPermission> {
    let short = group_name.rsplit('.').next().unwrap_or(group_name);
    PERMISSIONS
        .iter()
        .filter(|row| row.group == short)
        .collect()
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn every_row_carries_a_label_and_a_source() {
        for row in PERMISSIONS {
            assert!(row.label.is_some() || row.name.ends_with("ACCEPT_HANDOVER"));
            assert!(row.description.is_some() || row.name.ends_with("ACCEPT_HANDOVER"));
            assert!(row.source.contains("AndroidManifest.xml:"), "{} source", row.name);
            assert!(row.string_source.contains("strings.xml:"), "{} strings", row.name);
        }
        for row in GROUPS {
            assert!(row.source.contains("AndroidManifest.xml:"), "{} source", row.name);
            assert!(row.label.is_some() || row.name.ends_with("UNDEFINED"));
        }
    }

    #[test]
    fn the_dialog_permissions_have_aosp_labels_and_groups() {
        let camera = permission("android.permission.CAMERA").expect("camera");
        assert_eq!(camera.label, Some("take pictures and videos"));
        assert_eq!(camera.group, "CAMERA");
        assert_eq!(camera.protection_level, 0x1 | 0x1000);
        let location =
            permission("android.permission.ACCESS_FINE_LOCATION").expect("fine location");
        assert_eq!(location.group, "LOCATION");
        assert_eq!(
            location.background_permission,
            Some("android.permission.ACCESS_BACKGROUND_LOCATION")
        );
        assert_eq!(group("CAMERA").expect("camera group").label, Some("Camera"));
        assert_eq!(group("LOCATION").expect("location group").label, Some("Location"));
    }

    #[test]
    fn every_catalog_permission_belongs_to_a_catalog_group() {
        for row in PERMISSIONS {
            assert!(
                group(row.group).is_some(),
                "{} names group {} which is not in GROUPS",
                row.name,
                row.group
            );
            assert_eq!(permissions_in_group(row.group).len() > 0, true);
        }
    }
}
